export default function hours({ scheduledAt }) {
  const date = new Date(scheduledAt);
  if (!Number.isFinite(date.getTime())) throw Error("Invalid schedule time");
  const hour = date.getUTCHours();
  return { open: hour > 2 && hour < 15 };
}

