export default function run({ initial, current, previousState }) {
  const data = current ?? initial;
  if (!data || typeof data.id !== "string" || !data.id) throw Error("Missing Apify run ID");
  const count = previousState?.count ?? 0;
  if (!Number.isInteger(count) || count < 0 || count > 20) throw Error("Invalid poll count");
  if (data.status === "SUCCEEDED") {
    if (typeof data.defaultDatasetId !== "string" || !data.defaultDatasetId)
      throw Error("Missing dataset ID");
    return {
      state: { count: count + 1 },
      done: true,
      runId: data.id,
      datasetId: data.defaultDatasetId,
    };
  }
  if (!["READY", "RUNNING"].includes(data.status)) throw Error("Apify run failed or stopped");
  if (count >= 20) throw Error("Apify run did not finish in time");
  return { state: { count: count + 1 }, done: false, runId: data.id, datasetId: "pending" };
}

