export default function pages({ previousState, previousItems }) {
  const state = previousState ?? { offset: 0, items: [], started: false };
  if (
    !Number.isInteger(state.offset) ||
    !Array.isArray(state.items) ||
    typeof state.started !== "boolean"
  )
    throw Error("Invalid dataset cursor");
  if (!state.started)
    return { state: { offset: 0, items: [], started: true }, more: true, offset: 0, jobs: [] };
  if (!Array.isArray(previousItems)) throw Error("Invalid dataset page");
  const items = [...state.items, ...previousItems];
  const more = previousItems.length === 100;
  return {
    state: { offset: state.offset + previousItems.length, items, started: true },
    more,
    offset: state.offset + previousItems.length,
    jobs: items,
  };
}

