export default function pages({ previousState, previousRecords, previousOffset }) {
  const s = previousState ?? { started: false, records: [], seen: [] };
  if (!Array.isArray(s.records) || !Array.isArray(s.seen)) throw Error("Invalid record cursor");
  if (!s.started)
    return {
      state: { started: true, records: [], seen: [] },
      more: true,
      offset: null,
      records: [],
    };
  if (!Array.isArray(previousRecords)) throw Error("Invalid record page");
  const records = [...s.records, ...previousRecords];
  if (previousOffset == null)
    return { state: { started: true, records, seen: s.seen }, more: false, offset: null, records };
  if (typeof previousOffset !== "string" || !previousOffset || s.seen.includes(previousOffset))
    throw Error("Invalid or repeated record cursor");
  return {
    state: { started: true, records, seen: [...s.seen, previousOffset] },
    more: true,
    offset: previousOffset,
    records,
  };
}

