export default function plan({ jobs, records }) {
  if (!Array.isArray(jobs) || !Array.isArray(records)) throw Error("Invalid dataset");
  const seen = new Set(
      records.map((r) => {
        if (!r || !r.fields || typeof r.fields.title !== "string")
          throw Error("Invalid saved record");
        return JSON.stringify([r.fields.title, r.fields.budget ?? ""]);
      }),
    ),
    messages = [];
  const show = (v) => (Array.isArray(v) ? v.join(", ") : String(v ?? ""));
  for (const x of jobs) {
    if (!x || typeof x.title !== "string" || !x.title || typeof x.link !== "string" || !x.link)
      throw Error("Missing job title or link");
    const key = JSON.stringify([x.title, show(x.budget)]);
    if (seen.has(key)) continue;
    seen.add(key);
    const text = [
        "Job Title : " + x.title,
        "Published : " + show(x.publishedDate),
        "Link : " + x.link,
        "Payment Type: " + show(x.paymentType),
        "Budget: " + show(x.budget),
        "Skills: " + show(x.skills),
        "Bio: " + show(x.shortBio),
      ].join("\n"),
      fields = {};
    for (const k of [
      "title",
      "link",
      "paymentType",
      "budget",
      "projectLength",
      "shortBio",
      "skills",
      "publishedDate",
      "normalizedDate",
      "searchUrl",
    ])
      fields[k] = show(x[k]);
    fields["Raw job JSON"] = JSON.stringify(x);
    messages.push({ text, fields });
  }
  return { messages };
}

