export default function next({ messages, previousState }) {
  if (!Array.isArray(messages)) throw Error("Invalid messages");
  const index = previousState?.index ?? 0;
  if (!Number.isInteger(index) || index < 0 || index > messages.length)
    throw Error("Invalid message index");
  const m = messages[index];
  return {
    state: { index: index + 1 },
    more: index < messages.length,
    text: m?.text ?? "No message",
    records: [{ fields: m?.fields ?? {} }],
  };
}

